#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

int pow_mod(int a, int b, int mod) {
    int res = 1;
    while (b > 0) {
        if (b & 1) res = (1LL * res * a) % mod;
        a = (1LL * a * a) % mod;
        b >>= 1;
    }
    return res;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << pow_mod(p, p - 1, MOD) << endl;
    } else if (k == 1) {
        cout << pow_mod(p, p, MOD) << endl;
    } else {
        int ord = p - 1;
        int m = ord;
        for (int i = 2; i * i <= m; ++i) {
            if (m % i == 0) {
                while (m % i == 0 && pow_mod(k, ord / i, p) == 1) {
                    ord /= i;
                }
                while (m % i == 0) {
                    m /= i;
                }
            }
        }
        if (m > 1 && pow_mod(k, ord / m, p) == 1) {
            ord /= m;
        }
        cout << pow_mod(p, (p - 1) / ord, MOD) << endl;
    }
    return 0;
}

