using namespace std;

struct Event {
    int x1, x2, y;
    int type; // 1 for start, -1 for end
    Event(int x1, int x2, int y, int type) : x1(x1), x2(x2), y(y), type(type) {}
    bool operator<(const Event& other) const {
        if (y != other.y) return y < other.y;
        return type > other.type;
    }
};

long long compute_union(const vector<pair<int, int>>& segments) {
    if (segments.empty()) return 0;
    vector<pair<int, int>> temp = segments;
    sort(temp.begin(), temp.end());
    long long res = 0;
    int start = temp[0].first;
    int end = temp[0].second;
    for (size_t i = 1; i < temp.size(); ++i) {
        if (temp[i].first <= end) {
            end = max(end, temp[i].second);
        } else {
            res += end - start + 1;
            start = temp[i].first;
            end = temp[i].second;
        }
    }
    res += end - start + 1;
    return res;
}

long long solve_horizontal(vector<Event>& events) {
    sort(events.begin(), events.end());
    map<int, int> active;
    long long res = 0;
    int prev_y = -2e9;
    long long active_sum = 0;
    for (const Event& e : events) {
        if (e.y != prev_y && !active.empty()) {
            res += active_sum * (e.y - prev_y);
        }
        if (e.type == 1) {
            active[e.x1]++;
            active[e.x2 + 1]--;
        } else {
            active[e.x1]--;
            active[e.x2 + 1]++;
        }
        active_sum = 0;
        int cnt = 0;
        int prev = -2e9;
        for (const auto& p : active) {
            if (cnt > 0) {
                active_sum += p.first - prev;
            }
            cnt += p.second;
            prev = p.first;
        }
        prev_y = e.y;
    }
    return res;
}

