using namespace std;

struct Event {
    int x, y1, y2;
    bool isStart;
    Event(int x, int y1, int y2, bool isStart) : x(x), y1(y1), y2(y2), isStart(isStart) {}
};

bool compareEvents(const Event &a, const Event &b) {
    if (a.x != b.x) return a.x < b.x;
    return a.isStart > b.isStart;
}

long long calculateCovered(const vector<pair<int, int>> &segments) {
    if (segments.empty()) return 0;
    vector<Event> events;
    for (auto &seg : segments) {
        int y1 = seg.first, y2 = seg.second;
        if (y1 > y2) swap(y1, y2);
        events.emplace_back(y1, y1, y2, true);
        events.emplace_back(y2, y1, y2, false);
    }
    sort(events.begin(), events.end(), compareEvents);

    long long res = 0;
    map<int, int> active;
    int prevY = events[0].x;
    for (auto &event : events) {
        int currentY = event.x;
        if (!active.empty()) {
            int last = active.rbegin()->first;
            res += currentY - prevY;
        }
        if (event.isStart) {
            active[event.y2]++;
        } else {
            if (--active[event.y1] == 0) {
                active.erase(event.y1);
            }
        }
        prevY = currentY;
    }
    return res;
}

