        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 == x2) {
            vertical.emplace_back(min(y1, y2), max(y1, y2));
        } else {
            horizontal.emplace_back(min(x1, x2), max(x1, x2));
        }
    }

    sort(horizontal.begin(), horizontal.end());
    vector<pair<int, int>> mergedHoriz;
    for (auto &seg : horizontal) {
        if (mergedHoriz.empty()) {
            mergedHoriz.push_back(seg);
        } else {
            auto &last = mergedHoriz.back();
            if (seg.first <= last.second) {
                last.second = max(last.second, seg.second);
            } else {
                mergedHoriz.push_back(seg);
            }
        }
    }

    sort(vertical.begin(), vertical.end());
    vector<pair<int, int>> mergedVert;
    for (auto &seg : vertical) {
        if (mergedVert.empty()) {
            mergedVert.push_back(seg);
        } else {
            auto &last = mergedVert.back();
            if (seg.first <= last.second) {
                last.second = max(last.second, seg.second);
            } else {
                mergedVert.push_back(seg);
            }
        }
    }

    long long total = 0;
    for (auto &seg : mergedHoriz) {
        total += seg.second - seg.first + 1;
    }
    for (auto &seg : mergedVert) {
        total += seg.second - seg.first + 1;
    }

    vector<pair<int, int>> horizontalEvents, verticalEvents;
    for (auto &seg : mergedHoriz) {
        horizontalEvents.emplace_back(seg.first, seg.second);
    }
    for (auto &seg : mergedVert) {
        verticalEvents.emplace_back(seg.first, seg.second);
    }

    long long overlap = 0;
    map<int, vector<pair<int, int>>> horiLines, vertLines;
    for (auto &seg : mergedHoriz) {
        int y = seg.first;
        horiLines[y].emplace_back(seg.first, seg.second);
    }
    for (auto &seg : mergedVert) {
        int x = seg.first;
        vertLines[x].emplace_back(seg.first, seg.second);
    }

    for (auto &entry : horiLines) {
        int y = entry.first;
        if (vertLines.count(y)) {
            auto &hSegs = entry.second;
            auto &vSegs = vertLines[y];
            for (auto &hSeg : hSegs) {
