#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n + 1);
    vector<int> next_diff(n + 2);

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    next_diff[n] = n + 1;
    for (int i = n - 1; i >= 1; --i) {
        if (a[i] != a[i + 1]) {
            next_diff[i] = i + 1;
        } else {
            next_diff[i] = next_diff[i + 1];
        }
    }

    while (m--) {
        int l, r, x;
        cin >> l >> r >> x;
        if (a[l] != x) {
            cout << l << '\n';
        } else {
            if (next_diff[l] <= r) {
                cout << next_diff[l] << '\n';
            } else {
                cout << -1 << '\n';
            }
        }
    }

    return 0;
}

