#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 2e5 + 5;
const int MAX_VAL = 1e6 + 6;

int a[MAX_N];
vector<int> pos[MAX_VAL];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        pos[a[i]].push_back(i);
    }

    while (m--) {
        int l, r, x;
        cin >> l >> r >> x;

        auto it = lower_bound(pos[x].begin(), pos[x].end(), l);
        if (it == pos[x].end() || *it > r) {
            cout << l << '\n';
            continue;
        }

        int first_pos = *it;
        if (first_pos > l) {
            cout << l << '\n';
            continue;
        }

        it = upper_bound(pos[x].begin(), pos[x].end(), r);
        int last_pos = (it == pos[x].begin()) ? -1 : *(--it);
        if (last_pos < r) {
            cout << r << '\n';
            continue;
        }

        if (pos[x].size() == r - l + 1) {
            cout << -1 << '\n';
        } else {
            int left = 0, right = pos[x].size() - 1;
            int ans = -1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (pos[x][mid] - l > mid) {
                    ans = pos[x][mid] - 1;
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            cout << ans << '\n';
        }
    }

    return 0;
}

