#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, k, a, b, c, d;
    cin >> n >> k >> a >> b >> c >> d;

    if (n == 4 || k < n + 1) {
        cout << -1 << endl;
        return 0;
    }

    vector<int> path1, path2;
    vector<int> others;

    for (int i = 1; i <= n; ++i) {
        if (i != a && i != b && i != c && i != d) {
            others.push_back(i);
        }
    }

    path1.push_back(a);
    path1.push_back(c);
    for (int city : others) {
        path1.push_back(city);
    }
    path1.push_back(d);
    path1.push_back(b);

    path2.push_back(c);
    path2.push_back(a);
    for (int city : others) {
        path2.push_back(city);
    }
    path2.push_back(b);
    path2.push_back(d);

    for (int i = 0; i < n; ++i) {
        cout << path1[i] << " ";
    }
    cout << endl;

    for (int i = 0; i < n; ++i) {
        cout << path2[i] << " ";
    }
    cout << endl;

    return 0;
}

