    int size;

    SegmentTree(int n) {
        size = 1;
        while (size < n) size <<= 1;
        tree.resize(2 * size, {0, 0});
    }

    void update(int pos, int val) {
        pos += size;
        tree[pos] = {val, pos - size + 1};
        for (pos >>= 1; pos >= 1; pos >>= 1) {
            tree[pos] = max(tree[2 * pos], tree[2 * pos + 1]);
