#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
int parent[MAXN], visited[MAXN], a[MAXN], res[MAXN];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        parent[i] = a[i];
    }

    int root = -1;
    for (int i = 1; i <= n; ++i) {
        if (parent[i] == i) {
            root = i;
            break;
        }
    }

    int components = 0;
    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            int u = i;
            while (!visited[u]) {
                visited[u] = i;
                u = parent[u];
            }
            if (visited[u] == i) {
                if (root == -1) {
                    root = u;
                    parent[u] = u;
                    components++;
                }
                if (parent[u] != root) {
                    parent[u] = root;
                    components++;
                }
            }
        }
    }

    cout << components << "\n";
    for (int i = 1; i <= n; ++i) {
        cout << parent[i] << " ";
    }
    cout << "\n";

    return 0;
}

