const int MAXN = 200005;
int parent[MAXN];
bool visited[MAXN];
int a[MAXN];

int find_root(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void union_set(int x, int y) {
    int root_x = find_root(x);
    int root_y = find_root(y);
    if (root_x != root_y) {
        parent[root_x] = root_y;
    }
}

