        if (steps % 3 == 0) {
            a = b + c - 1;
        } else if (steps % 3 == 1) {
            b = a + c - 1;
        } else {
            c = a + b - 1;
        }
        steps++;
        a = min(a, x);
        b = min(b, x);
        c = min(c, x);
    }
    cout << steps << endl;
    return 0;
}

