#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    map<long long, int> count;
    while (t--) {
        char op;
        string s;
        cin >> op >> s;
        long long pattern = 0;
        for (char c : s) {
            int digit = c - '0';
            pattern = (pattern << 1) | (digit % 2);
        }
        if (op == '+') {
            count[pattern]++;
        } else if (op == '-') {
            count[pattern]--;
        } else {
            cout << count[pattern] << '\n';
        }
    }
    return 0;
}

