        cin >> op;
        if (op == '+' || op == '-') {
            long long num;
            cin >> num;
            long long key = 0;
            long long place = 1;
            while (num > 0) {
                int digit = num % 10;
                key += (digit % 2) * place;
                place *= 10;
                num /= 10;
            }
            if (op == '+') {
                count[key]++;
            } else {
                count[key]--;
            }
        } else {
            string s;
            cin >> s;
            long long key = 0;
            for (char c : s) {
                key = key * 10 + (c - '0');
            }
            cout << count[key] << '\n';
        }
    }
    return 0;
}

