#include <iostream>
#include <vector>
#include <string>
#include <sstream>
using namespace std;

bool isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'y';
}

int countSyllables(const string& word) {
    int count = 0;
    bool inSyllable = false;
    for (char c : word) {
        if (isVowel(c)) {
            if (!inSyllable) {
                count++;
                inSyllable = true;
            }
        } else {
            inSyllable = false;
        }
    }
    return count;
}

int main() {
    int n;
    cin >> n;
    vector<int> pattern(n);
    for (int i = 0; i < n; ++i) {
        cin >> pattern[i];
    }
    cin.ignore(); // To ignore the newline after reading n and pattern

    bool matches = true;
    for (int i = 0; i < n; ++i) {
        string line;
        getline(cin, line);
        istringstream iss(line);
        string word;
        int total = 0;
        while (iss >> word) {
            int syllables = countSyllables(word);
            total += syllables;
        }
        if (total != pattern[i]) {
            matches = false;
        }
    }

    cout << (matches ? "YES" : "NO") << endl;
    return 0;
}

