#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int lcm(int a, int b) {
    if (a == 0 || b == 0) {
        return 0;
    }
    return (a / gcd(a, b)) * b;
}

int main() {
    int n;
    cin >> n;
    vector<int> crush(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> crush[i];
    }

    vector<bool> visited(n + 1, false);
    int total_lcm = 1;

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            int current = i;
            int cycle_length = 0;
            while (!visited[current]) {
                visited[current] = true;
                current = crush[current];
                cycle_length++;
            }
            if (current != i) {
                cout << -1 << endl;
                return 0;
            }
            if (cycle_length % 2 == 0) {
                cycle_length /= 2;
            }
            total_lcm = lcm(total_lcm, cycle_length);
        }
    }

    cout << total_lcm << endl;
    return 0;
}

