#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, q;
    cin >> n >> q;
    vector<int> busy_until(n + 1, 0); // 1-based indexing

    while (q--) {
        int t, k, d;
        cin >> t >> k >> d;
        vector<int> available;
        for (int i = 1; i <= n; ++i) {
            if (busy_until[i] <= t) {
                available.push_back(i);
            }
        }
        if (available.size() >= k) {
            int sum = 0;
            for (int i = 0; i < k; ++i) {
                int server = available[i];
                sum += server;
                busy_until[server] = t + d;
            }
            cout << sum << endl;
        } else {
            cout << -1 << endl;
        }
    }
    return 0;
}

