                available.push_back(server);
                if (available.size() == k) break;
            }
        }
        if (available.size() >= k) {
            int sum = 0;
            for (int j = 0; j < k; ++j) {
                int server = available[j];
                sum += server;
                busy_until[server] = t + d;
            }
            cout << sum << endl;
        } else {
            cout << -1 << endl;
        }
    }
    return 0;
}

