#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    cin >> m;
    vector<int> b(m);
    for (int i = 0; i < m; ++i) {
        cin >> b[i];
    }

    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    vector<vector<pair<int, int>>> prev(n + 1, vector<pair<int, int>>(m + 1, {-1, -1}));

    for (int i = 1; i <= n; ++i) {
        int best_val = 0;
        pair<int, int> best_prev = {-1, -1};
        for (int j = 1; j <= m; ++j) {
            dp[i][j] = dp[i - 1][j];
            prev[i][j] = prev[i - 1][j];
            if (a[i - 1] == b[j - 1]) {
                if (best_val + 1 > dp[i][j]) {
                    dp[i][j] = best_val + 1;
                    prev[i][j] = best_prev;
                }
            }
            if (b[j - 1] < a[i - 1] && dp[i - 1][j] > best_val) {
                best_val = dp[i - 1][j];
                best_prev = {i - 1, j};
            }
        }
    }

    int max_len = 0;
    pair<int, int> pos = {-1, -1};
    for (int j = 1; j <= m; ++j) {
        if (dp[n][j] > max_len) {
            max_len = dp[n][j];
            pos = {n, j};
        }
    }

    cout << max_len << endl;
    if (max_len == 0) {
        return 0;
    }

    vector<int> lcis;
    while (pos.first != -1 && pos.second != -1) {
        if (a[pos.first - 1] == b[pos.second - 1]) {
            lcis.push_back(b[pos.second - 1]);
            pos = prev[pos.first][pos.second];
        } else {
            pos = prev[pos.first][pos.second];
        }
    }
    reverse(lcis.begin(), lcis.end());
    for (int i = 0; i < lcis.size(); ++i) {
        if (i > 0) cout << " ";
        cout << lcis[i];
    }
    cout << endl;

    return 0;
}

