#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>
#include <set>

using namespace std;

struct Item {
    string name;
    string cls;
    int atk;
    int def;
    int res;
    int size;
    vector<string> residents;
};

struct Resident {
    string name;
    string type;
    int bonus;
    string home;
};

int main() {
    int n;
    cin >> n;
    vector<Item> items(n);
    map<string, int> itemIndex;
    for (int i = 0; i < n; ++i) {
        cin >> items[i].name >> items[i].cls >> items[i].atk >> items[i].def >> items[i].res >> items[i].size;
        itemIndex[items[i].name] = i;
    }

    int k;
    cin >> k;
    vector<Resident> residents(k);
    map<string, int> residentIndex;
    for (int i = 0; i < k; ++i) {
        cin >> residents[i].name >> residents[i].type >> residents[i].bonus >> residents[i].home;
        residentIndex[residents[i].name] = i;
        int idx = itemIndex[residents[i].home];
        items[idx].residents.push_back(residents[i].name);
    }

    vector<int> weaponIndices, armorIndices, orbIndices;
    for (int i = 0; i < n; ++i) {
        if (items[i].cls == "weapon") weaponIndices.push_back(i);
        else if (items[i].cls == "armor") armorIndices.push_back(i);
        else if (items[i].cls == "orb") orbIndices.push_back(i);
    }

    vector<vector<string>> bestWeaponResidents;
    vector<vector<string>> bestArmorResidents;
    vector<vector<string>> bestOrbResidents;
    int maxAtk = -1, maxDef = -1, maxRes = -1;
    int bestWeapon = -1, bestArmor = -1, bestOrb = -1;

    for (int wi : weaponIndices) {
        for (int ai : armorIndices) {
            for (int oi : orbIndices) {
                vector<string> weaponResidents, armorResidents, orbResidents;
                int totalAtk = items[wi].atk;
                int totalDef = items[ai].def;
                int totalRes = items[oi].res;

                vector<Resident> gladiators, sentries, physicians;
                for (const auto& res : residents) {
                    if (res.type == "gladiator") gladiators.push_back(res);
                    else if (res.type == "sentry") sentries.push_back(res);
                    else if (res.type == "physician") physicians.push_back(res);
                }

                sort(gladiators.begin(), gladiators.end(), [](const Resident& a, const Resident& b) {
                    return a.bonus > b.bonus;
                });
                sort(sentries.begin(), sentries.end(), [](const Resident& a, const Resident& b) {
                    return a.bonus > b.bonus;
                });
                sort(physicians.begin(), physicians.end(), [](const Resident& a, const Resident& b) {
                    return a.bonus > b.bonus;
                });

                int weaponSpace = items[wi].size - items[wi].residents.size();
                int armorSpace = items[ai].size - items[ai].residents.size();
                int orbSpace = items[oi].size - items[oi].residents.size();

                for (int i = 0; i < gladiators.size() && weaponSpace > 0; ++i) {
                    totalAtk += gladiators[i].bonus;
                    weaponResidents.push_back(gladiators[i].name);
                    weaponSpace--;
                }
                for (int i = 0; i < sentries.size() && armorSpace > 0; ++i) {
                    totalDef += sentries[i].bonus;
                    armorResidents.push_back(sentries[i].name);
                    armorSpace--;
                }
                for (int i = 0; i < physicians.size() && orbSpace > 0; ++i) {
                    totalRes += physicians[i].bonus;
                    orbResidents.push_back(physicians[i].name);
                    orbSpace--;
                }

                if (totalAtk > maxAtk || 
                    (totalAtk == maxAtk && totalDef > maxDef) || 
                    (totalAtk == maxAtk && totalDef == maxDef && totalRes > maxRes)) {
                    maxAtk = totalAtk;
                    maxDef = totalDef;
                    maxRes = totalRes;
                    bestWeapon = wi;
                    bestArmor = ai;
                    bestOrb = oi;
                    bestWeaponResidents.clear();
                    bestArmorResidents.clear();
                    bestOrbResidents.clear();
                    bestWeaponResidents.push_back(weaponResidents);
                    bestArmorResidents.push_back(armorResidents);
                    bestOrbResidents.push_back(orbResidents);
                } else if (totalAtk == maxAtk && totalDef == maxDef && totalRes == maxRes) {
                    bestWeaponResidents.push_back(weaponResidents);
                    bestArmorResidents.push_back(armorResidents);
                    bestOrbResidents.push_back(orbResidents);
                }
            }
        }
    }

    cout << items[bestWeapon].name << " ";
    vector<string> finalWeaponResidents = items[bestWeapon].residents;
    if (!bestWeaponResidents.empty()) {
        for (const auto& res : bestWeaponResidents[0]) {
            finalWeaponResidents.push_back(res);
        }
    }
    cout << finalWeaponResidents.size();
    for (const auto& res : finalWeaponResidents) {
        cout << " " << res;
    }
    cout << endl;

    cout << items[bestArmor].name << " ";
    vector<string> finalArmorResidents = items[bestArmor].residents;
    if (!bestArmorResidents.empty()) {
        for (const auto& res : bestArmorResidents[0]) {
            finalArmorResidents.push_back(res);
        }
    }
    cout << finalArmorResidents.size();
    for (const auto& res : finalArmorResidents) {
        cout << " " << res;
    }
