#include <iostream>
#include <vector>
#include <climits>

using namespace std;

struct Laptop {
    int speed;
    int ram;
    int hdd;
    int cost;
    int index;
};

int main() {
    int n;
    cin >> n;
    vector<Laptop> laptops(n);
    for (int i = 0; i < n; ++i) {
        cin >> laptops[i].speed >> laptops[i].ram >> laptops[i].hdd >> laptops[i].cost;
        laptops[i].index = i + 1;
    }

    vector<bool> outdated(n, false);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            if (laptops[i].speed < laptops[j].speed && 
                laptops[i].ram < laptops[j].ram && 
                laptops[i].hdd < laptops[j].hdd) {
                outdated[i] = true;
                break;
            }
        }
    }

    int min_cost = INT_MAX;
    int result = -1;
    for (int i = 0; i < n; ++i) {
        if (!outdated[i] && laptops[i].cost < min_cost) {
            min_cost = laptops[i].cost;
            result = laptops[i].index;
        }
    }

    cout << result << endl;
    return 0;
}

