#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>

using namespace std;

int n, m;
vector<vector<char>> grid;
vector<vector<bool>> visited;
vector<pair<int, int>> pigs, wolves;

bool isAdjacent(const pair<int, int>& wolf, const pair<int, int>& pig) {
    int dx = abs(wolf.first - pig.first);
    int dy = abs(wolf.second - pig.second);
    return (dx == 1 && dy == 0) || (dx == 0 && dy == 1);
}

int main() {
    cin >> n >> m;
    grid.resize(n, vector<char>(m));
    visited.resize(n, vector<bool>(m, false));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> grid[i][j];
            if (grid[i][j] == 'P') {
                pigs.emplace_back(i, j);
            } else if (grid[i][j] == 'W') {
                wolves.emplace_back(i, j);
            }
        }
    }

    int count = 0;
    for (auto& wolf : wolves) {
        for (auto& pig : pigs) {
            if (!visited[pig.first][pig.second] && isAdjacent(wolf, pig)) {
                visited[pig.first][pig.second] = true;
                count++;
                break;
            }
        }
    }

    cout << count << endl;
    return 0;
}

