#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

bool isLucky(int num) {
    if (num == 0) return false;
    while (num > 0) {
        int digit = num % 10;
        if (digit != 4 && digit != 7) return false;
        num /= 10;
    }
    return true;
}

int countLuckyNumbers(int n) {
    int count = 0;
    for (int i = 1; i <= n; ++i) {
        if (isLucky(i)) {
            ++count;
        }
    }
    return count;
}

int main() {
    int n, k;
    cin >> n >> k;

    int m = 1;
    long long fact = 1;
    while (fact < k && m <= 20) {
        ++m;
        fact *= m;
    }

    if (m > n) {
        cout << -1 << endl;
        return 0;
    }

    int fixed_part = n - m;
    int result = countLuckyNumbers(fixed_part);

    vector<int> perm(m);
    for (int i = 0; i < m; ++i) {
        perm[i] = fixed_part + 1 + i;
    }

    --k;
    for (int i = 0; i < m; ++i) {
        fact /= (m - i);
        int pos = k / fact;
        int num = perm[pos];
        if (isLucky(fixed_part + 1 + i) && isLucky(num)) {
            ++result;
        }
        perm.erase(perm.begin() + pos);
        k %= fact;
    }

    cout << result << endl;
    return 0;
}

