#include <iostream>
#include <string>
#include <vector>
#include <queue>
using namespace std;

struct State {
    int pos, len;
    string s;
    State(int pos, int len, string s) : pos(pos), len(len), s(s) {}
    bool operator<(const State& other) const {
        return s > other.s;
    }
};

int main() {
    string str;
    cin >> str;
    int k;
    cin >> k;
    priority_queue<State> pq;
    int n = str.size();
    for (int i = 0; i < n; ++i) {
        string s(1, str[i]);
        pq.push(State(i, 1, s));
    }
    string result = "No such line.";
    while (!pq.empty() && k > 0) {
        State current = pq.top();
        pq.pop();
        k--;
        if (k == 0) {
            result = current.s;
            break;
        }
        if (current.pos + current.len < n) {
            pq.push(State(current.pos, current.len + 1, current.s + str[current.pos + current.len]));
        }
    }
    cout << result << endl;
    return 0;
}

