#include <bits/stdc++.h>
using namespace std;

struct State {
    int len, link;
    map<char, int> next;
};

const int MAXLEN = 100000;
State st[MAXLEN * 2];
int sz, last;
int cnt[MAXLEN * 2];
vector<int> order;

void sa_init() {
    st[0].len = 0;
    st[0].link = -1;
    sz = 1;
    last = 0;
}

void sa_extend(char c) {
    int p = last;
    int curr = sz++;
    st[curr].len = st[p].len + 1;
    cnt[curr] = 1;
    while (p != -1 && !st[p].next.count(c)) {
        st[p].next[c] = curr;
        p = st[p].link;
    }
    if (p == -1) {
        st[curr].link = 0;
    } else {
        int q = st[p].next[c];
        if (st[p].len + 1 == st[q].len) {
            st[curr].link = q;
        } else {
            int clone = sz++;
            st[clone].len = st[p].len + 1;
            st[clone].next = st[q].next;
            st[clone].link = st[q].link;
            while (p != -1 && st[p].next[c] == q) {
                st[p].next[c] = clone;
                p = st[p].link;
            }
            st[q].link = clone;
            st[curr].link = clone;
        }
    }
    last = curr;
}

void build_order() {
    order.resize(sz);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [](int a, int b) {
        return st[a].len > st[b].len;
    });
    for (int u : order) {
        if (st[u].link != -1) {
            cnt[st[u].link] += cnt[u];
        }
    }
}

string find_kth(int k) {
    string res;
    int u = 0;
    while (k > 0) {
        for (auto &p : st[u].next) {
            if (cnt[p.second] < k) {
                k -= cnt[p.second];
            } else {
                res += p.first;
                u = p.second;
                k--;
                break;
            }
        }
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int k;
    cin >> k;

    sa_init();
    for (char c : s) {
        sa_extend(c);
    }
    build_order();

    long long total = 0;
    for (int i = 1; i < sz; ++i) {
        total += st[i].len - st[st[i].link].len;
    }

    if (total < k) {
        cout << "No such line." << endl;
    } else {
        cout << find_kth(k) << endl;
    }

    return 0;
}

