#include <iostream>
#include <vector>
using namespace std;

const int MOD = 1000000007;

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    if (2 * k > n - 1 || 2 * k > m - 1) {
        cout << 0 << endl;
        return 0;
    }

    vector<vector<long long>> C(n, vector<long long>(m, 0));

    for (int i = 0; i < n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
    }

    long long res = (C[n-1][2*k] * C[m-1][2*k]) % MOD;
    cout << res << endl;

    return 0;
}

