#include <iostream>
#include <algorithm>

using namespace std;

int sumDigits(int n, int base) {
    int sum = 0;
    while (n > 0) {
        sum += n % base;
        n /= base;
    }
    return sum;
}

int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    int A;
    cin >> A;
    int totalSum = 0;
    for (int base = 2; base < A; ++base) {
        totalSum += sumDigits(A, base);
    }
    int denominator = A - 2;
    int commonDivisor = gcd(totalSum, denominator);
    cout << totalSum / commonDivisor << "/" << denominator / commonDivisor << endl;
    return 0;
}

