bool isPunctuation(char c) {
    return c == ',' || c == '.' || c == '!' || c == '?';
}

int main() {
    string line;
    getline(cin, line);
    vector<char> result;
    bool inWord = false;
    bool spacePending = false;

    for (char c : line) {
        if (isalpha(c)) {
            if (spacePending && !isPunctuation(result.back())) {
                result.push_back(' ');
            }
            result.push_back(c);
            inWord = true;
            spacePending = false;
        } else if (isPunctuation(c)) {
            result.push_back(c);
            spacePending = true;
            inWord = false;
        } else if (isspace(c)) {
            if (inWord) {
                spacePending = true;
                inWord = false;
            }
        }
    }

    for (char c : result) {
