int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double a, d;
    cin >> n >> a >> d;

    vector<double> arrival_times(n);

    for (int i = 0; i < n; ++i) {
        double t, v;
        cin >> t >> v;

        double time_to_max_speed = v / a;
        double distance_to_max_speed = 0.5 * a * time_to_max_speed * time_to_max_speed;

        double total_time;
        if (distance_to_max_speed >= d) {
            total_time = sqrt(2 * d / a);
        } else {
            total_time = time_to_max_speed + (d - distance_to_max_speed) / v;
        }

        double arrival_time = t + total_time;
        if (i > 0) {
            arrival_time = max(arrival_time, arrival_times[i-1]);
        }
        arrival_times[i] = arrival_time;
    }

    cout << fixed << setprecision(10);
    for (double time : arrival_times) {
        cout << time << "\n";
    }

    return 0;
}

