    cin >> n >> a >> d;

    vector<double> arrival_times(n);

    for (int i = 0; i < n; ++i) {
        double ti, vi;
        cin >> ti >> vi;

        // Time to reach max speed: t_acc = v / a
        double t_acc = vi / a;
        // Distance covered during acceleration: d_acc = 0.5 * a * t_acc^2
        double d_acc = 0.5 * a * t_acc * t_acc;

        double total_time;
        if (d_acc >= d) {
            // Doesn't reach max speed
            total_time = sqrt(2.0 * d / a);
        } else {
            // Reaches max speed, then cruises
            double remaining_d = d - d_acc;
            total_time = t_acc + remaining_d / vi;
        }

        // The actual arrival time is the later of ti + total_time or the previous trolley's arrival time
        if (i == 0) {
            arrival_times[i] = ti + total_time;
        } else {
            arrival_times[i] = max(ti + total_time, arrival_times[i - 1]);
        }
    }

    cout << fixed << setprecision(10);
    for (double time : arrival_times) {
