    if (n == 0) {
        cout << 1 << endl;
    } else {
        long long ans = (fast_pow(2, 2 * n) + fast_pow(2, n)) % MOD;
        ans = ans * 333333336 % MOD; // 333333336 is the modular inverse of 3 under MOD
        cout << ans << endl;
    }
    return 0;
}

