int countInversions(const vector<string>& original, const vector<string>& perm) {
    int inv = 0;
    for (int i = 0; i < perm.size(); ++i) {
        for (int j = i + 1; j < perm.size(); ++j) {
            auto it1 = find(original.begin(), original.end(), perm[i]);
            auto it2 = find(original.begin(), original.end(), perm[j]);
            if (it1 > it2) {
                inv++;
            }
        }
    }
    return inv;
}

