using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    long long total_sum = accumulate(a.begin(), a.end(), 0LL);
    if (total_sum % 3 != 0) {
        cout << 0 << endl;
        return 0;
    }

    long long target = total_sum / 3;
    long long current_sum = 0;
    vector<int> prefix_counts(n, 0);

    for (int i = 0; i < n - 1; ++i) {
        current_sum += a[i];
        if (current_sum == target) {
            prefix_counts[i] = 1;
        }
    }

    for (int i = 1; i < n; ++i) {
        prefix_counts[i] += prefix_counts[i - 1];
    }

    current_sum = 0;
    long long answer = 0;

    for (int i = n - 1; i >= 1; --i) {
        current_sum += a[i];
        if (current_sum == target) {
            if (i - 1 >= 0) {
                answer += prefix_counts[i - 1];
            }
        }
    }

    cout << answer << endl;
    return 0;
}

