    for (int v : adj[u]) {
        if (v != parent) {
            dfs(v, u);
            size[u] += size[v];
        }
    }
}

long long solve(int u, int k, int parent) {
    if (k == 0) return 1;
    if (dp[u][k] != -1) return dp[u][k];
    vector<long long> temp(k + 1, 0);
    temp[0] = 1;
    for (int v : adj[u]) {
        if (v == parent) continue;
        vector<long long> new_temp(k + 1, 0);
        for (int i = 0; i <= k; ++i) {
            if (temp[i] == 0) continue;
            for (int j = 0; j <= min(size[v], k - i); ++j) {
