        if (is_prime[i]) {
            for (int j = i * i; j <= MAX; j += i) {
                is_prime[j] = false;
            }
        }
    }
    for (int i = 2; i <= MAX; ++i) {
        if (is_prime[i]) {
            primes.push_back(i);
        }
    }
}

bool is_t_prime(long long x) {
    long long s = sqrt(x);
    if (s * s != x) {
        return false;
    }
    return binary_search(primes.begin(), primes.end(), s);
}

