#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, d;
    cin >> n >> d;
    vector<int> x(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i];
    }

    long long res = 0;
    for (int i = 0; i < n; ++i) {
        int j = upper_bound(x.begin(), x.end(), x[i] + d) - x.begin();
        long long cnt = j - i - 1;
        if (cnt >= 2) {
            res += cnt * (cnt - 1) / 2;
        }
    }

    cout << res << endl;
    return 0;
}

