#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

vector<int> applyPermutation(const vector<int>& p, const vector<int>& q) {
    vector<int> res(p.size());
    for (int i = 0; i < p.size(); ++i) {
        res[i] = p[q[i] - 1];
    }
    return res;
}

vector<int> applyInversePermutation(const vector<int>& p, const vector<int>& q) {
    vector<int> res(p.size());
    for (int i = 0; i < p.size(); ++i) {
        res[q[i] - 1] = p[i];
    }
    return res;
}

bool isPossible(int n, int k, const vector<int>& q, const vector<int>& s) {
    vector<int> current(n);
    for (int i = 0; i < n; ++i) {
        current[i] = i + 1;
    }

    bool found = false;
    int stepsForward = 0;
    while (stepsForward <= k) {
        if (current == s) {
            found = true;
            break;
        }
        current = applyPermutation(current, q);
        stepsForward++;
    }
    if (found && stepsForward == k) {
        return true;
    }

    current = vector<int>(n);
    for (int i = 0; i < n; ++i) {
        current[i] = i + 1;
    }
    int stepsBackward = 0;
    while (stepsBackward <= k) {
        if (current == s) {
            found = true;
            break;
        }
        current = applyInversePermutation(current, q);
        stepsBackward++;
    }
    if (found && stepsBackward == k) {
        return true;
    }

    if (!found) {
        return false;
    }

    if (stepsForward <= k && (k - stepsForward) % 2 == 0 && stepsForward != 0) {
        return true;
    }
    if (stepsBackward <= k && (k - stepsBackward) % 2 == 0 && stepsBackward != 0) {
        return true;
    }

    return false;
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<int> q(n);
    for (int i = 0; i < n; ++i) {
        cin >> q[i];
    }
    vector<int> s(n);
    for (int i = 0; i < n; ++i) {
        cin >> s[i];
    }

    vector<int> initial(n);
    for (int i = 0; i < n; ++i) {
        initial[i] = i + 1;
    }
    if (initial == s) {
        cout << "NO" << endl;
        return 0;
    }

    bool possible = isPossible(n, k, q, s);
    cout << (possible ? "YES" : "NO") << endl;

    return 0;
}

