#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> species(n);
    for (int i = 0; i < n; ++i) {
        double x;
        cin >> species[i] >> x;
    }

    vector<int> dp(n, 1);
    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (species[j] <= species[i]) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
    }

    int max_len = *max_element(dp.begin(), dp.end());
    cout << n - max_len << endl;

    return 0;
}

