    if (current_divisors == n) {
        if (current_num < res) {
            res = current_num;
        }
        return;
    }
    if (pos >= primes.size()) return;
    for (int e = 1; e <= max_exp; ++e) {
        if (current_num > res / primes[pos]) break;
        current_num *= primes[pos];
        if (n % (current_divisors * (e + 1)) == 0) {
            dfs(pos + 1, e, current_num, current_divisors * (e + 1));
        }
    }
}

