int n, m;
vector<Point> nails;
vector<int> rods;
vector<int> assignment;

bool check() {
    vector<bool> used(m + 1, false);
    for (int i = 0; i < n; ++i) {
        if (assignment[i] == -1) continue;
        if (assignment[i] < 1 || assignment[i] > m) return false;
        if (used[assignment[i]]) return false;
        used[assignment[i]] = true;
    }

    for (int i = 0; i < n; ++i) {
        int prev = (i - 1 + n) % n;
        int next = (i + 1) % n;

        if (assignment[i] != -1) {
            int rod = assignment[i];
            int len = rods[rod - 1];

            int dx1 = nails[i].x - nails[prev].x;
            int dy1 = nails[i].y - nails[prev].y;
            int dist1 = abs(dx1) + abs(dy1);

            int dx2 = nails[next].x - nails[i].x;
            int dy2 = nails[next].y - nails[i].y;
            int dist2 = abs(dx2) + abs(dy2);

            if (dist1 + dist2 != 2 * len) {
                return false;
            }
        } else {
            int dx1 = nails[i].x - nails[prev].x;
            int dy1 = nails[i].y - nails[prev].y;
            int dx2 = nails[next].x - nails[i].x;
            int dy2 = nails[next].y - nails[i].y;

            if ((dx1 != 0 && dy1 != 0) || (dx2 != 0 && dy2 != 0)) {
                return false;
            }

            if ((dx1 == 0 && dy2 == 0) || (dy1 == 0 && dx2 == 0)) {
                continue;
            } else {
                return false;
            }
        }
    }
    return true;
}

bool solve(int pos, vector<bool>& used) {
    if (pos == n) {
        return check();
    }

    if (assignment[pos] != 0) {
        return solve(pos + 1, used);
    }

    for (int rod = 1; rod <= m; ++rod) {
        if (!used[rod]) {
            used[rod] = true;
            assignment[pos] = rod;
            if (solve(pos + 1, used)) {
                return true;
            }
            assignment[pos] = 0;
            used[rod] = false;
        }
    }

    assignment[pos] = -1;
    if (solve(pos + 1, used)) {
        return true;
    }
    assignment[pos] = 0;

    return false;
}

