#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int power(int x, int y, int p) {
    int res = 1;
    x = x % p;
    while (y > 0) {
        if (y & 1)
            res = (res * x) % p;
        y = y >> 1;
        x = (x * x) % p;
    }
    return res;
}

bool isPrimitiveRoot(int x, int p) {
    for (int i = 1; i <= p - 2; ++i) {
        if (power(x, i, p) == 1) {
            return false;
        }
    }
    return (power(x, p - 1, p) == 1);
}

int main() {
    int p;
    cin >> p;
    int count = 0;
    for (int x = 1; x < p; ++x) {
        if (isPrimitiveRoot(x, p)) {
            ++count;
        }
    }
    cout << count << endl;
    return 0;
}

