    int phi = p - 1;
    vector<int> factors;
    int temp = phi;
    for (int i = 2; i * i <= temp; ++i) {
        if (temp % i == 0) {
            factors.push_back(i);
            while (temp % i == 0)
                temp /= i;
        }
    }
    if (temp > 1)
        factors.push_back(temp);
    for (int factor : factors) {
        if (power(x, phi / factor, p) == 1)
            return false;
    }
    return true;
}

