#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

int power(int a, int b, int mod) {
    int res = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1)
            res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return res;
}

int gcd(int a, int b) {
    while (b) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int find_primitive_roots(int p) {
    if (p == 2) return 1;

    vector<int> factors;
    int phi = p - 1;
    int n = phi;

    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            while (n % i == 0)
                n /= i;
        }
    }
    if (n > 1)
        factors.push_back(n);

    int count = 0;
    for (int x = 1; x < p; ++x) {
        if (gcd(x, p) != 1)
            continue;
        bool ok = true;
        for (int f : factors) {
            if (power(x, phi / f, p) == 1) {
                ok = false;
                break;
            }
        }
        if (ok)
            count++;
    }
    return count;
}

int main() {
    int p;
    cin >> p;
    cout << find_primitive_roots(p) << endl;
    return 0;
}

