    unordered_map<int, vector<int>> adj;
    unordered_map<int, int> degree;

    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
        degree[a]++;
        degree[b]++;
    }

    int start = -1;
    for (auto& p : degree) {
        if (p.second == 1) {
            start = p.first;
            break;
        }
    }

    vector<int> route;
    route.push_back(start);

    int prev = -1;
    int current = start;

    while (route.size() <= n) {
        for (int neighbor : adj[current]) {
            if (neighbor != prev) {
                route.push_back(neighbor);
                prev = current;
                current = neighbor;
                break;
            }
        }
    }

    for (int city : route) {
        cout << city << " ";
    }
    cout << endl;

    return 0;
}

