using namespace std;

struct Vehicle {
    int type;
    int capacity;
    int index;
};

bool compareCapacity(const Vehicle &a, const Vehicle &b) {
    return a.capacity > b.capacity;
}

int main() {
    int n, v;
    cin >> n >> v;
    vector<Vehicle> kayaks, catamarans;
    for (int i = 0; i < n; ++i) {
        int t, p;
        cin >> t >> p;
        if (t == 1) {
            kayaks.push_back({t, p, i + 1});
        } else {
            catamarans.push_back({t, p, i + 1});
        }
    }

    sort(kayaks.begin(), kayaks.end(), compareCapacity);
    sort(catamarans.begin(), catamarans.end(), compareCapacity);

    vector<long long> kayakPrefix(kayaks.size() + 1, 0);
    for (int i = 0; i < kayaks.size(); ++i) {
        kayakPrefix[i + 1] = kayakPrefix[i] + kayaks[i].capacity;
    }

    vector<long long> catamaranPrefix(catamarans.size() + 1, 0);
    for (int i = 0; i < catamarans.size(); ++i) {
        catamaranPrefix[i + 1] = catamaranPrefix[i] + catamarans[i].capacity;
    }

    long long maxCapacity = 0;
    int bestK = 0, bestC = 0;
    int maxK = min((int)kayaks.size(), v);
