    size_t i = 0;
    while (i < s.size()) {
        if (s[i] == '@') {
            if (i + 1 >= s.size()) {
                return {};
            }
            size_t next_at = s.find('@', i + 1);
            if (next_at == string::npos) {
                current += s.substr(i);
                if (!isValidEmail(current)) {
                    return {};
                }
                emails.push_back(current);
