#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

using namespace std;

vector<string> operations;

bool all_ones(const vector<int>& nums) {
    for (int num : nums) {
        if (num != 1) return false;
    }
    return true;
}

bool solve(vector<int>& nums) {
    if (all_ones(nums)) return true;

    for (int i = 0; i < 4; ++i) {
        int j = (i + 1) % 4;
        if (nums[i] % 2 == 0 && nums[j] % 2 == 0) {
            nums[i] /= 2;
            nums[j] /= 2;
            operations.push_back("/" + to_string(i + 1));
            if (solve(nums)) return true;
            operations.pop_back();
            nums[i] *= 2;
            nums[j] *= 2;
        }
    }

    for (int i = 0; i < 4; ++i) {
        int j = (i + 1) % 4;
        nums[i]++;
        nums[j]++;
        operations.push_back("+" + to_string(i + 1));
        if (operations.size() > 1000) {
            nums[i]--;
            nums[j]--;
            operations.pop_back();
            return false;
        }
        if (solve(nums)) return true;
        operations.pop_back();
        nums[i]--;
        nums[j]--;
    }

