struct State {
    vector<int> nums;
    string ops;
    bool operator<(const State& other) const {
        return nums < other.nums;
    }
};

bool isTarget(const vector<int>& nums) {
    for (int num : nums) {
        if (num != 1) return false;
    }
    return true;
}

string solveSafe(const vector<int>& initial) {
    queue<State> q;
    map<vector<int>, string> visited;

    State start;
    start.nums = initial;
    start.ops = "";
    q.push(start);
    visited[start.nums] = "";

    while (!q.empty()) {
        State current = q.front();
        q.pop();

        if (isTarget(current.nums)) {
            return current.ops;
        }

        if (current.ops.size() > 1000) {
            continue;
        }

        for (int i = 0; i < 4; ++i) {
            int j = (i + 1) % 4;

            // Try addition
            vector<int> nextAdd = current.nums;
            nextAdd[i]++;
            nextAdd[j]++;
            string newOpsAdd = current.ops + "+" + to_string(i + 1);
            if (visited.find(nextAdd) == visited.end()) {
                State nextStateAdd;
                nextStateAdd.nums = nextAdd;
                nextStateAdd.ops = newOpsAdd;
                q.push(nextStateAdd);
                visited[nextAdd] = newOpsAdd;
            }

            // Try division if both are even
            if (current.nums[i] % 2 == 0 && current.nums[j] % 2 == 0) {
                vector<int> nextDiv = current.nums;
                nextDiv[i] /= 2;
