                int trees = prefix[i][j] - prefix[i - b][j] - prefix[i][j - a] + prefix[i - b][j - a];
                if (trees < min_trees) {
                    min_trees = trees;
                }
            }
        }
    }

    cout << min_trees << endl;
    return 0;
