#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int l = -1, r = -1;
    for (int i = 0; i < n; ++i) {
        if (a[i] != i + 1) {
            l = i + 1;
            break;
        }
    }
    for (int i = n - 1; i >= 0; --i) {
        if (a[i] != i + 1) {
            r = i + 1;
            break;
        }
    }

    if (l == -1 || r == -1) {
        cout << "0 0" << endl;
        return 0;
    }

    // Reverse the segment from l to r
    int i = l - 1, j = r - 1;
    while (i < j) {
        swap(a[i], a[j]);
        i++;
        j--;
    }

    // Check if the entire array is now sorted
    bool sorted = true;
    for (int i = 0; i < n; ++i) {
        if (a[i] != i + 1) {
            sorted = false;
            break;
        }
    }

    if (sorted) {
        cout << l << " " << r << endl;
    } else {
        cout << "0 0" << endl;
    }

    return 0;
}

