    for (int i = 0; i < k; ++i) {
        cin >> wastes[i].first >> wastes[i].second;
    }

    sort(wastes.begin(), wastes.end());

    while (t--) {
        int i, j;
        cin >> i >> j;

        auto it = lower_bound(wastes.begin(), wastes.end(), make_pair(i, j));
        if (it != wastes.end() && *it == make_pair(i, j)) {
            cout << "Waste\n";
            continue;
        }

        int pos = (i - 1) * m + j;
        int waste_before = lower_bound(wastes.begin(), wastes.end(), make_pair(i, j)) - wastes.begin();
        pos -= waste_before;

        if (pos % 3 == 1) {
            cout << "Carrots\n";
        } else if (pos % 3 == 2) {
            cout << "Kiwis\n";
        } else {
            cout << "Grapes\n";
        }
    }

    return 0;
}

