#include <string>
#include <algorithm>
using namespace std;

long long reflection(long long n) {
    string s = to_string(n);
    for (char &c : s) {
        c = '0' + (9 - (c - '0'));
    }
    // Remove leading zeros
    size_t pos = s.find_first_not_of('0');
    if (pos != string::npos) {
        s = s.substr(pos);
    } else {
        s = "0";
    }
    return stoll(s);
}

long long max_weight(long long l, long long r) {
    long long max_prod = 0;
    // Check around the middle point where the reflection is maximized
    string s = to_string(r);
    string candidate_str = "";
    for (int i = 0; i < s.size(); ++i) {
        if (s[i] >= '5') {
            candidate_str += '5';
        } else {
            candidate_str += s[i];
        }
    }
    for (int i = 0; i < candidate_str.size(); ++i) {
        if (candidate_str[i] == '5') {
            string temp1 = candidate_str;
            temp1[i] = '4';
            for (int j = i + 1; j < temp1.size(); ++j) {
                temp1[j] = '9';
            }
            string temp2 = candidate_str;
            temp2[i] = '5';
            for (int j = i + 1; j < temp2.size(); ++j) {
                temp2[j] = '9';
            }
            long long num1 = stoll(temp1);
            long long num2 = stoll(temp2);
            if (num1 >= l && num1 <= r) {
                long long prod = num1 * reflection(num1);
                if (prod > max_prod) {
                    max_prod = prod;
                }
            }
            if (num2 >= l && num2 <= r) {
                long long prod = num2 * reflection(num2);
                if (prod > max_prod) {
                    max_prod = prod;
                }
            }
        }
    }
    long long candidate = stoll(candidate_str);
