        cin >> a[i];
    }

    vector<long long> dp(n + 1, 0);
    vector<int> max_len(n + 1, 0);
    vector<int> min_sub(n + 1, INT_MAX);

    dp[0] = 1;
    max_len[0] = 0;
    min_sub[0] = 0;

    for (int i = 1; i <= n; ++i) {
        int current_min_len = INT_MAX;
        for (int j = 1; j <= i; ++j) {
            int c = s[i - j] - 'a';
            current_min_len = min(current_min_len, a[c]);
            if (j > current_min_len) break;

            dp[i] = (dp[i] + dp[i - j]) % MOD;
