#include <iostream>
#include <vector>
#include <algorithm>
#include <map>
using namespace std;

struct Ring {
    int a, b, h;
};

bool compare(const Ring &x, const Ring &y) {
    if (x.b != y.b) return x.b > y.b;
    return x.a > y.a;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Ring> rings(n);
    for (int i = 0; i < n; ++i) {
        cin >> rings[i].a >> rings[i].b >> rings[i].h;
    }
    sort(rings.begin(), rings.end(), compare);
    map<int, long long> dp;
    dp[0] = 0;
    long long max_height = 0;
    for (const auto &ring : rings) {
        auto it = dp.upper_bound(ring.b - 1);
        --it;
        long long current = it->second + ring.h;
        max_height = max(max_height, current);
        it = dp.lower_bound(ring.a);
        while (it != dp.end() && it->second <= current) {
            auto next = it;
            ++next;
            dp.erase(it);
            it = next;
        }
        dp[ring.a] = current;
    }
    cout << max_height << '\n';
    return 0;
}

