    vector<Ring> rings(n);
    for (int i = 0; i < n; ++i) {
        cin >> rings[i].a >> rings[i].b >> rings[i].h;
    }
    sort(rings.begin(), rings.end(), compare);

    vector<long long> dp(n);
    dp[0] = rings[0].h;
    long long max_height = dp[0];

    map<int, long long> prefix_max;
    prefix_max[rings[0].b] = dp[0];

    for (int i = 1; i < n; ++i) {
        auto it = prefix_max.upper_bound(rings[i].b);
        if (it != prefix_max.begin()) {
            --it;
            dp[i] = it->second + rings[i].h;
        } else {
            dp[i] = rings[i].h;
        }

        it = prefix_max.lower_bound(rings[i].b);
        while (it != prefix_max.end() && it->second <= dp[i]) {
            auto next_it = next(it);
            prefix_max.erase(it);
            it = next_it;
        }
        if (prefix_max.lower_bound(rings[i].b) == prefix_max.end() || prefix_max.lower_bound(rings[i].b)->second < dp[i]) {
            prefix_max[rings[i].b] = dp[i];
        }
        max_height = max(max_height, dp[i]);
    }
    cout << max_height << '\n';
    return 0;
}

