#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int current_gcd = a[0];
    for (int i = 1; i < n; ++i) {
        current_gcd = gcd(current_gcd, a[i]);
        if (current_gcd == 1) {
            break;
        }
    }

    if (current_gcd > 1) {
        cout << "YES\n0\n";
        return 0;
    }

    int operations = 0;
    for (int i = 0; i < n - 1; ++i) {
        if (a[i] % 2 != 0) {
            if (a[i + 1] % 2 != 0) {
                operations++;
                a[i + 1] = 0;
            } else {
                operations += 2;
            }
            a[i] = 0;
        }
    }

    if (a.back() % 2 != 0) {
        operations += 2;
    }

    current_gcd = a[0];
    for (int i = 1; i < n; ++i) {
        current_gcd = gcd(current_gcd, a[i]);
    }

    if (current_gcd > 1) {
        cout << "YES\n" << operations << "\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

