#include <bits/stdc++.h>
using namespace std;

int solve(int a, int b, int h, int w, vector<int>& extensions) {
    if ((h >= a && w >= b) || (h >= b && w >= a)) {
        return 0;
    }
    sort(extensions.rbegin(), extensions.rend());
    int n = extensions.size();
    set<pair<int, int>> current;
    current.insert({h, w});
    for (int i = 0; i < n; ++i) {
        set<pair<int, int>> next;
        for (auto [x, y] : current) {
            long long new_x = min(1LL * x * extensions[i], 100000LL);
            long long new_y = min(1LL * y * extensions[i], 100000LL);
            if ((new_x >= a && y >= b) || (new_x >= b && y >= a) ||
                (x >= a && new_y >= b) || (x >= b && new_y >= a)) {
                return i + 1;
            }
            next.insert({new_x, y});
            next.insert({x, new_y});
        }
        for (auto p : next) {
            current.insert(p);
        }
    }
    return -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, h, w, n;
    cin >> a >> b >> h >> w >> n;
    vector<int> extensions(n);
    for (int i = 0; i < n; ++i) {
        cin >> extensions[i];
    }
    int result = solve(a, b, h, w, extensions);
    cout << result << '\n';
    return 0;
}

