using namespace std;

int solve() {
    int a, b, h, w, n;
    cin >> a >> b >> h >> w >> n;
    vector<int> extensions(n);
    for (int i = 0; i < n; ++i) {
        cin >> extensions[i];
    }
    sort(extensions.rbegin(), extensions.rend());

    if ((h >= a && w >= b) || (h >= b && w >= a)) {
        return 0;
    }

    auto check = [&](int k) {
        set<pair<int, int>> visited;
        queue<pair<int, int>> q;
        q.push({h, w});
        visited.insert({h, w});
        for (int i = 0; i < k; ++i) {
            int ai = extensions[i];
            int sz = q.size();
            while (sz--) {
                auto [x, y] = q.front();
                q.pop();
                if (x < a) {
                    long long nx = x * ai;
                    if (nx > 1e5) nx = 1e5;
                    if (nx >= a && y >= b) return true;
                    if (nx * y >= (long long)a * b && y >= b) return true;
                    if (nx * y >= (long long)a * b && nx >= a) return true;
                    auto key = make_pair((int)nx, y);
                    if (!visited.count(key)) {
                        visited.insert(key);
                        q.push(key);
                    }
                }
                if (y < b) {
                    long long ny = y * ai;
                    if (ny > 1e5) ny = 1e5;
                    if (x >= a && ny >= b) return true;
                    if (x * ny >= (long long)a * b && ny >= b) return true;
                    if (x * ny >= (long long)a * b && x >= a) return true;
                    auto key = make_pair(x, (int)ny);
                    if (!visited.count(key)) {
                        visited.insert(key);
                        q.push(key);
                    }
                }
            }
        }
        while (!q.empty()) {
            auto [x, y] = q.front();
            q.pop();
            if ((x >= a && y >= b) || (x >= b && y >= a)) {
                return true;
            }
        }
        return false;
    };

    int left = 0, right = min(n, 40), ans = -1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (check(mid)) {
            ans = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return ans;
}

int main() {
    cout << solve() << endl;
    return 0;
}

