#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

const int SAMPLE_SIZE = 250;

double poisson_prob(int k, double lambda) {
    return exp(-lambda) * pow(lambda, k) / tgamma(k + 1);
}

double compute_poisson_log_likelihood(const vector<int>& samples, double lambda) {
    double log_likelihood = 0.0;
    for (int k : samples) {
        log_likelihood += log(poisson_prob(k, lambda));
    }
    return log_likelihood;
}

double compute_uniform_log_likelihood(const vector<int>& samples, int p) {
    double prob = 1.0 / (2 * p + 1);
    return samples.size() * log(prob);
}

int main() {
    int V;
    cin >> V;
    while (V--) {
        vector<int> samples(SAMPLE_SIZE);
        for (int i = 0; i < SAMPLE_SIZE; ++i) {
            cin >> samples[i];
        }

        double mean = 0.0;
        for (int k : samples) {
            mean += k;
        }
        mean /= SAMPLE_SIZE;

        double poisson_ll = compute_poisson_log_likelihood(samples, mean);

        int max_k = *max_element(samples.begin(), samples.end());
        int p_uniform = max_k / 2;
        double uniform_ll = compute_uniform_log_likelihood(samples, p_uniform);

        if (poisson_ll > uniform_ll) {
            cout << "poisson\n";
        } else {
            cout << "uniform\n";
        }
    }
    return 0;
}

