#include <vector>
#include <unordered_set>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    long long total_sum = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        total_sum += a[i];
    }
    if (total_sum % 2 != 0) {
        cout << "NO\n";
        return 0;
    }
    long long half = total_sum / 2;
    unordered_set<long long> prefix_sums;
    long long current_sum = 0;
    for (int i = 0; i < n; ++i) {
        current_sum += a[i];
        prefix_sums.insert(a[i]);
        long long diff = current_sum - half;
        if (diff == 0 || (diff > 0 && prefix_sums.count(diff))) {
            cout << "YES\n";
            return 0;
        }
    }
    unordered_set<long long> suffix_sums;
    current_sum = 0;
    for (int i = n - 1; i >= 0; --i) {
        current_sum += a[i];
        suffix_sums.insert(a[i]);
        long long diff = current_sum - half;
        if (diff == 0 || (diff > 0 && suffix_sums.count(diff))) {
            cout << "YES\n";
            return 0;
        }
    }
    cout << "NO\n";
