#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    if (n == 3) {
        cout << "2\n";
        cout << "3 1 2 3\n";
        cout << "3 1 2 3\n";
        return 0;
    }

    if (n % 2 != 0) {
        cout << "-1\n";
        return 0;
    }

    vector<vector<int>> cycles;

    for (int i = 1; i <= n; i += 2) {
        int a = i, b = i + 1;
        cycles.push_back({3, a, b, (b % n) + 1});
        cycles.push_back({3, a, b, (b % n) + 1});

        int c = (b % n) + 1;
        if (c % 2 == 0) {
            c = (c % n) + 1;
        } else {
            c = ((c + 1) % n) + 1;
        }

        cycles.push_back({4, a, b, c, (a % n) + 1});
        cycles.push_back({4, a, b, c, (a % n) + 1});
    }

    cout << cycles.size() << "\n";
    for (auto &cycle : cycles) {
        cout << cycle[0];
        for (size_t i = 1; i < cycle.size(); ++i) {
            cout << " " << cycle[i];
        }
        cout << "\n";
    }

    return 0;
}

