#include <bits/stdc++.h>
using namespace std;

const int INF = 2e9;
const int MAX = 2e5 + 5;

struct Voucher {
    int l, r, cost, duration;
};

vector<Voucher> vouchers;
vector<pair<int, int>> best_duration[MAX];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x;
    cin >> n >> x;
    vouchers.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> vouchers[i].l >> vouchers[i].r >> vouchers[i].cost;
        vouchers[i].duration = vouchers[i].r - vouchers[i].l + 1;
        if (vouchers[i].duration <= x) {
            best_duration[vouchers[i].duration].emplace_back(vouchers[i].l, vouchers[i].cost);
        }
    }

    for (int d = 0; d < MAX; ++d) {
        sort(best_duration[d].begin(), best_duration[d].end());
        for (int i = (int)best_duration[d].size() - 2; i >= 0; --i) {
            best_duration[d][i].second = min(best_duration[d][i].second, best_duration[d][i+1].second);
        }
    }

    int min_total = INF;
    for (const auto& voucher : vouchers) {
        int d = voucher.duration;
        int needed_d = x - d;
        if (needed_d <= 0 || needed_d >= MAX) continue;
        const auto& list = best_duration[needed_d];
        if (list.empty()) continue;

        int max_l = voucher.r + 1;
        auto it = lower_bound(list.begin(), list.end(), make_pair(max_l, -1));
        if (it != list.end()) {
            min_total = min(min_total, voucher.cost + it->second);
        }
    }

    if (min_total == INF) {
        cout << -1 << endl;
    } else {
        cout << min_total << endl;
    }

    return 0;
}

