#include <queue>
#include <climits>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    vector<vector<int>> pos(100001);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        pos[a[i]].push_back(i);
    }

    sort(a.begin(), a.end());
    int current_min_index = 0;
    int last_pos = -1;
    long long res = 0;

    while (current_min_index < n) {
        int current_min = a[current_min_index];
        auto &indices = pos[current_min];
        auto it = upper_bound(indices.begin(), indices.end(), last_pos);
        if (it == indices.end()) {
            res += n - last_pos - 1;
            last_pos = -1;
            it = upper_bound(indices.begin(), indices.end(), last_pos);
        }
        res += *it - last_pos;
        last_pos = *it;
        current_min_index += 1;
    }

    cout << res << '\n';
    return 0;
}

