#include <iomanip>
using namespace std;

vector<vector<int>> adj;
vector<double> res;

void dfs(int u, int parent, double prob, int depth) {
    int children = 0;
    for (int v : adj[u]) {
        if (v != parent) {
            children++;
        }
    }
    if (children == 0) {
        res[u] = depth * prob;
        return;
    }
    double new_prob = prob / children;
    for (int v : adj[u]) {
        if (v != parent) {
            dfs(v, u, new_prob, depth + 1);
        }
    }
}

int main() {
    int n;
    cin >> n;
    adj.resize(n + 1);
    res.resize(n + 1, 0.0);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
